-- Starter content for the Krish portfolio (generated from src/data/*.ts).
-- Run once in the Supabase SQL editor AFTER schema.sql. Safe to re-run: existing rows are left alone.

insert into posts (slug, title, excerpt, category, date, status, blocks) values
  ('learning-to-code-with-just-a-laptop', 'Learning to code with just a laptop', 'No coding classes, no tech background in Pundri. Just curiosity, a laptop, and a lot of late nights.', 'Journey', '2026-09-22', 'published', '[{"type":"p","text":"I''m a Class 12 student from a small town. There was no coding class to join and nobody around me who worked in tech. What I had was a laptop and a stubborn habit of asking \"but how does that actually work?\""},{"type":"h2","text":"Where I started"},{"type":"p","text":"I began with Python because it let me see results fast. Print a line, change a number, run it again. That tight loop of trying something and seeing what happens is what made me stay."},{"type":"h2","text":"What actually helped"},{"type":"list","items":["Building small things instead of only watching tutorials.","Reading error messages slowly instead of panicking at them.","Writing down what I learned so I could explain it to myself later."]},{"type":"quote","text":"I''m not chasing certificates — I''m chasing the ability to build things that actually work."},{"type":"p","text":"I''m still early in this journey. This blog is where I''ll keep track of it: what I build, what breaks, and what I figure out along the way."}]'::jsonb),
  ('python-c-and-cpp-what-each-one-taught-me', 'Python, C and C++: what each one taught me', 'Three languages, three different ways of thinking. Here is what I took from each.', 'Learning', '2026-09-15', 'published', '[{"type":"p","text":"Learning more than one language early on turned out to be less about syntax and more about how each one makes you think."},{"type":"h2","text":"Python — thinking in ideas"},{"type":"p","text":"Python let me focus on the logic. When I had an idea, I could test it in minutes, which made it the best place to learn how loops, functions, and data structures fit together."},{"type":"h2","text":"C — thinking in memory"},{"type":"p","text":"C removed the safety net. Suddenly I had to care about types, memory, and what the machine is really doing. It was frustrating and it was the most useful thing I learned."},{"type":"h2","text":"C++ — thinking in structure"},{"type":"p","text":"C++ added classes and objects on top, which pushed me to organise code into pieces that make sense on their own."},{"type":"code","lang":"python","text":"def greet(name):\n    return f\"Hello, {name}!\"\n\nprint(greet(\"world\"))"},{"type":"p","text":"Same idea, three languages, three different ways of getting there."}]'::jsonb),
  ('what-a-memory-match-game-taught-me-about-state', 'What a memory match game taught me about state', 'A simple card game is a great way to learn how state changes and events work together.', 'Projects', '2026-09-08', 'published', '[{"type":"p","text":"My Memory Match game looks simple, but it forced me to think carefully about state: which cards are flipped, which are matched, and what is allowed to happen next."},{"type":"h2","text":"State first, screen second"},{"type":"p","text":"The biggest lesson was to decide what the game needs to remember before drawing anything. Once the state was clear, the screen simply followed it."},{"type":"code","lang":"js","text":"const state = {\n  flipped: [],\n  matched: [],\n  locked: false,\n};"},{"type":"h2","text":"Events need rules"},{"type":"p","text":"Clicking fast, clicking the same card twice, clicking while two cards are being compared — every one of those is a bug waiting to happen. Writing the rules down made them easy to handle."},{"type":"quote","text":"Most bugs are just a missing rule about what should happen next."}]'::jsonb),
  ('how-i-use-ai-tools-without-outsourcing-my-thinking', 'How I use AI tools without outsourcing my thinking', 'AI can speed me up, but only if I stay the one who understands the code.', 'AI', '2026-08-30', 'published', '[{"type":"p","text":"I use AI tools every day for learning and building. The rule I try to follow is simple: I should be able to explain everything I ship."},{"type":"h2","text":"What I use them for"},{"type":"list","items":["Explaining a concept a different way when a tutorial did not click.","Reviewing my code and pointing out things I missed.","Getting unstuck, then going back to write the solution myself."]},{"type":"h2","text":"What I try not to do"},{"type":"p","text":"Paste an answer I do not understand. If I cannot explain a line, I have not learned it yet — I have just borrowed it."},{"type":"quote","text":"A tool should make me faster at thinking, not a replacement for it."}]'::jsonb),
  ('what-digital-marketing-with-ai-taught-me', 'What Digital Marketing with AI taught me about building for people', 'Finishing a Digital Marketing with AI certification changed how I think about the things I build.', 'Marketing', '2026-08-18', 'published', '[{"type":"p","text":"This year I completed a Digital Marketing with AI certification. I expected to learn tools. I also learned to think about who the work is for."},{"type":"h2","text":"Good software still needs to be found"},{"type":"p","text":"SEO, ads, and social media are really about one thing: helping the right person find something useful. A great project nobody can find does not help anyone."},{"type":"h2","text":"What I am taking with me"},{"type":"list","items":["Start with the audience, then decide the message.","Measure what happens instead of guessing.","Clear writing is a skill worth practising just like code."]},{"type":"p","text":"Web development and digital marketing feel like two halves of the same idea: build something good, then make sure people can reach it."}]'::jsonb)
on conflict (slug) do nothing;

insert into projects (name, description, url, position)
select * from (values
  ('Fitness Temple', 'A fitness-themed website built to practice front-end structure, content hierarchy, and styling.', 'https://github.com/krish-khati/FITNESS_TEMPLE', 0),
  ('LinguaBridge', 'A language-learning and translation project exploring the small details that help communication travel.', 'https://github.com/krish-khati/LINGUABRIDGE-', 1),
  ('Memory Match Game', 'An interactive memory game built around logic, state changes, and event-driven programming.', 'https://github.com/krish-khati/MEMORY-MATCH', 2),
  ('Calculator', 'A functional calculator application focused on core programming logic and arithmetic operations.', '', 3)
) as v(name, description, url, position)
where not exists (select 1 from projects);

insert into site_settings (id, data) values (1, '{"name":"Krish","tagline":"I''m passionate about creating modern web experiences, exploring the power of AI and digital marketing, and building things that make an impact.","email":"krrishai0916@gmail.com","phone":"+91 93060 91154","location":"Pundri, Kaithal, Haryana, India","roles":["Web Developer","Digital Marketer","AI Enthusiast"],"instagram":"https://instagram.com","linkedin":"https://www.linkedin.com/in/krish-khati/","youtube":"https://youtube.com","github":"https://github.com/krish-khati"}'::jsonb)
on conflict (id) do nothing;
